// examprep.js — không phải đổi cấu trúc).
//
// Unit: {
//   id: string,               // duy nhất toàn hệ thống, tiền tố theo cấp: 'starters-...' / 'movers-...' / 'flyers-...' / 'ket-...' / 'pet-...' / 'toefl-junior-...' / 'toeic-...'
//   level: 'starters'|'movers'|'flyers'|'ket'|'pet'|'toefl-junior'|'toeic',
//   topic: string,             // tên hiển thị tiếng Việt
//   grammarPoints: string[],   // các điểm ngữ pháp/nội dung unit này luyện (hiển thị + đối chiếu về sau)
//   vocab: string[],           // từ vựng cốt lõi dùng trong câu ví dụ
//   lesson: {                  // nội dung "Học" — đọc trước khi luyện tập
//     intro: string,           // 1 câu tổng quan tiếng Việt
//     points: [{ rule: string, examples: [{ en: string, vi: string }] }],
//   },
//   passage: { title: string, text: string } | undefined, // TUỲ CHỌN — đoạn văn đọc hiểu
//                             // dùng chung cho MỌI câu hỏi type:'reading' của unit này (đúng format
//                             // "Đọc Hiểu Có Giờ" ở mục 30 §4); engine gắn passage vào từng câu qua
//                             // allQuestions() để UI hiển thị lại đúng đoạn văn khi câu đó xuất hiện.
//   questions: Question[],
// }
// Question: {
//   id: string,        // duy nhất toàn hệ thống — dùng làm khoá cho sổ "câu hay sai" (misses.js)
//   type: 'grammar'|'vocab'|'reading'|'rewrite', // để hiển thị/thống kê — engine không phân biệt xử lý
//   prompt: string,    // câu hỏi tiếng Anh — có chỗ trống "___" (grammar/vocab/rewrite, "rewrite" dùng
//                       // "câu gốc. → ___" làm prompt) HOẶC câu hỏi đọc hiểu đầy đủ không cần chỗ
//                       // trống (reading, đi kèm Unit.passage)
//   options: string[], // các lựa chọn
//   answer: number,    // chỉ số đáp án đúng trong options
//   explain: string,   // giải thích ngắn bằng tiếng Việt
// }

